    session: SwipeSession,
    current: SwipePreview,
  ): SwipeCommit | null => {
    const outcome = decideWorkspaceSwipe({
      deltaX: session.deltaX,
      velocityX: session.velocityX,
      width: session.width,
      allowsCommandCenter,
    });
