      host === null ||
      event.defaultPrevented ||
      event.pointerType !== "touch" ||
      event.button !== 0 ||
      sessionRef.current !== null ||
      settleTimerRef.current !== null ||
      shouldIgnoreWorkspaceSwipeTarget(event.target)
    ) {
      return;
    }

