    <div
      ref={hostRef}
      data-workspace-swipe-host=""
      onPointerDown={handlePointerDown}
      // Cancels the app layout's page padding so the surface travels to the
      // real screen edges; each layer re-applies it (see SWIPE_LAYER_CLASS).
