import { useSplitWorkspaceActive } from "@/hooks/useSplitWorkspaceActive";
import { maximizedPaneIdAtom, splitLayoutAtom } from "@/lib/split-layout/atoms";
import {
  clampSplitPairFraction,
  computePaneRects,
  countPanes,
  findPane,
  listPanes,
  movePane,
  removePane,
  replacePaneContent,
  resizeSplit,
