@layer base {
  /*
   * Sonner clips collapsed native toasts on the toast node. Our custom card
   * lives inside that node, so clip it there too when it is behind the front
   * toast in the stack.
   */
  :where(
    [data-sonner-toast].bb-app-toast[data-expanded="false"][data-front="false"]
  ) {
    overflow: hidden;
    border-radius: var(--radius-md);
  }

  /*
   * Opt out of the global thin scrollbar for horizontally-scrolling strips
   * (e.g. the secondary-panel tab strip) where the scrollbar would clutter a
   * short row. The element still scrolls; only the scrollbar chrome is hidden.
   */
  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }

  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }

  /*
   * Keep reading surfaces visually quiet at rest while preserving the native
   * scroll container, its hit area, and its layout geometry. The scroll owner
   * briefly sets `data-scrollbar-scrolling` for real scroll events, matching
   * the platform's transient scrollbar behavior without making content reflow
   * as the thumb appears.
   */
  .thread-scrollbar,
  .transient-scrollbar {
    scrollbar-color: transparent transparent;
  }

  .thread-scrollbar::-webkit-scrollbar-thumb,
  .thread-scrollbar::-webkit-scrollbar-thumb:hover,
  .transient-scrollbar::-webkit-scrollbar-thumb,
  .transient-scrollbar::-webkit-scrollbar-thumb:hover {
    background-color: transparent;
  }

  .thread-scrollbar[data-scrollbar-scrolling="true"],
  .transient-scrollbar[data-scrollbar-scrolling="true"] {
    scrollbar-color: color-mix(in oklab, var(--foreground) 20%, transparent)
      transparent;
  }

  .thread-scrollbar[data-scrollbar-scrolling="true"]::-webkit-scrollbar-thumb,
  .transient-scrollbar[data-scrollbar-scrolling="true"]::-webkit-scrollbar-thumb {
    background-color: color-mix(in oklab, var(--foreground) 20%, transparent);
  }

  .thread-scrollbar[data-scrollbar-scrolling="true"]::-webkit-scrollbar-thumb:hover,
  .transient-scrollbar[data-scrollbar-scrolling="true"]::-webkit-scrollbar-thumb:hover {
    background-color: color-mix(in oklab, var(--foreground) 40%, transparent);
  }

  /*
   * Opt out of the global thin scrollbar into always-visible classic
   * scrollbars for two-axis data surfaces (e.g. the CSV table preview).
   * Native thin scrollbars render as macOS overlay bars that fade out and
   * give a wide table no persistent horizontal-scroll affordance. Chromium
   * only honors `::-webkit-scrollbar` customization when `scrollbar-width`
   * and `scrollbar-color` are both `auto`, so those resets are what
   * re-enable the persistent chrome below.
   */
  .persistent-scrollbar {
    scrollbar-width: auto;
    scrollbar-color: auto;
  }

  .persistent-scrollbar::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  .persistent-scrollbar::-webkit-scrollbar-track,
  .persistent-scrollbar::-webkit-scrollbar-corner {
    background: transparent;
  }

  .persistent-scrollbar::-webkit-scrollbar-thumb {
    background-color: color-mix(in oklab, var(--foreground) 20%, transparent);
    border-radius: 9999px;
    border: 2px solid transparent;
    background-clip: padding-box;
  }

  .persistent-scrollbar::-webkit-scrollbar-thumb:hover {
    background-color: color-mix(in oklab, var(--foreground) 40%, transparent);
  }

  /*
   * Soft right-edge fade for single-line text that is clipped horizontally
   * (e.g. a queued-message preview). Fades the text out instead of a hard
   * `…` ellipsis. Self-gating: short text doesn't reach the fade zone, so the
   * fade only shows when content is actually truncated. Pair with
   * `overflow-hidden whitespace-nowrap` (no scroll).
   */
  .fade-clip-right {
    -webkit-mask-image: linear-gradient(
      to right,
      #000 calc(100% - 1.5rem),
      transparent
    );
    mask-image: linear-gradient(
      to right,
      #000 calc(100% - 1.5rem),
      transparent
    );
  }
}

/* Sweep the purple gradient across the `ultracode` glyphs. */
@keyframes ultracode-shimmer {
  0% {
    background-position: 200% 0%;
  }
  100% {
    background-position: -200% 0%;
  }
}

/* Twinkle each corner sparkle: fade in, scale up, and spin a quarter turn. */
@keyframes ultracode-sparkle {
  0%,
  100% {
    opacity: 0;
    transform: scale(0.4) rotate(0deg);
  }
  50% {
    opacity: 1;
    transform: scale(1) rotate(90deg);
  }
}

/* Briefly highlight a conversation message that a sidebar search result
 * deep-links to, then fade back to transparent. */
@keyframes bb-search-flash {
  from {
    background-color: color-mix(in oklch, var(--ring) 22%, transparent);
  }
  to {
    background-color: transparent;
  }
}

.bb-search-flash {
  border-radius: var(--radius-lg, 0.5rem);
  animation: bb-search-flash 1.6s ease-out;
}

@media (prefers-reduced-motion: reduce) {
  .bb-search-flash {
    animation: none;
  }
}

