      settingsSections: [],
      navPanels: [
        {
          id: "docs",
          title: "Docs",
          icon: "FileText",
          path: "docs",
          component: () => <div>Docs panel</div>,
          headerContent: () => (
            <button type="button">Toggle docs sidebar</button>
          ),
