    expect(breadcrumb.textContent).toContain("Automations");
    expect(breadcrumb.textContent).toContain("Installed");
    expect(breadcrumb.textContent).toContain("weekly-review");

    store.set(resourceRouteLabelAtom, "Weekly review");
