function threadPath(threadId: string): string {
  return `/threads/${threadId}`;
}

function LocationProbe() {
  const location = useLocation();
  return <div data-testid="location">{location.pathname}</div>;
}

/** Surfaces whether the current entry carries a validated Command Center intent. */
function CommandCenterStateProbe() {
  const navigation = parseCommandCenterNavigation(useLocation().state);
  return (
    <div data-testid="command-center-state">
      {navigation === null
        ? "none"
        : `${navigation.returnPath}|${navigation.returnPaneId}`}
    </div>
  );
}

function stubMediaQueries(isMatch: (query: string) => boolean) {
  vi.stubGlobal("matchMedia", (query: string) => ({
    matches: isMatch(query),
    media: query,
    onchange: null,
    addListener: () => {},
    removeListener: () => {},
    addEventListener: () => {},
    removeEventListener: () => {},
    dispatchEvent: () => false,
  }));
}

// The capability reads the real display-mode query, so drive that query rather
// than stubbing the capability out — the gate is part of what these tests check.
function stubStandaloneDisplayMode(isStandalone: boolean) {
  stubMediaQueries(
    (query) => isStandalone && query === STANDALONE_DISPLAY_MODE_QUERY,
  );
}

function storedSplitLayout(store: ReturnType<typeof createStore>): SplitLayout {
  const layout = store.get(splitLayoutAtom);
  if (layout === null) {
    throw new Error("Expected a stored split layout");
  }
  return layout;
}

function paneContents(store: ReturnType<typeof createStore>) {
  return listPanes(storedSplitLayout(store).root).map((pane) => pane.content);
}

function ExternalNav({ to }: { to: string }) {
  const navigate = useNavigate();
  return (
    <button
      type="button"
      data-testid="external-nav"
      onClick={() => navigate(to)}
    >
      go
    </button>
  );
}

function RouteAwareSplitArea() {
  const location = useLocation();
  return (
    <SplitThreadArea
      routeContent={
        location.pathname.startsWith("/plugins/") ? docsContent : undefined
      }
    />
  );
}

/** Mirrors SplitWorkspaceRoute: "/" is compose, thread URLs self-resolve. */
function WorkspaceRouteSplitArea() {
  const location = useLocation();
  return (
    <SplitThreadArea
      routeContent={location.pathname === "/" ? newThreadContent : undefined}
    />
  );
}

function HistoryForwardNav() {
  const navigate = useNavigate();
  return (
    <button
      type="button"
      data-testid="history-forward"
      onClick={() => navigate(1)}
    >
      forward
    </button>
  );
}

function renderSplitArea(options: {
  path: string;
  layout?: SplitLayout;
  externalTo?: string;
  locationState?: unknown;
  /** Extra history entries below `path`, oldest first. */
  historyEntries?: string[];
  routeContent?: PaneContent;
  routeAwareContent?: boolean;
  workspaceRouteContent?: boolean;
  maximizedPaneId?: string;
}) {
  const store = createStore();
  if (options.layout !== undefined) {
    store.set(splitLayoutAtom, options.layout);
  }
  if (options.maximizedPaneId !== undefined) {
    store.set(maximizedPaneIdAtom, options.maximizedPaneId);
  }
  const initialEntries = [
    ...(options.historyEntries ?? []).map((pathname) => ({
      pathname,
      state: null,
    })),
    { pathname: options.path, state: options.locationState ?? null },
  ];
  render(
    <TooltipProvider>
      <JotaiProvider store={store}>
        <QueryClientProvider client={queryClient}>
          <MemoryRouter
            initialEntries={initialEntries}
            initialIndex={initialEntries.length - 1}
          >
            {options.routeAwareContent ? (
              <RouteAwareSplitArea />
            ) : options.workspaceRouteContent ? (
              <WorkspaceRouteSplitArea />
            ) : (
              <SplitThreadArea routeContent={options.routeContent} />
            )}
            <LocationProbe />
            <CommandCenterStateProbe />
            <HistoryForwardNav />
            {options.externalTo !== undefined ? (
              <ExternalNav to={options.externalTo} />
            ) : null}
          </MemoryRouter>
        </QueryClientProvider>
      </JotaiProvider>
    </TooltipProvider>,
  );
  return store;
}

beforeEach(() => {
  experimentState.enabled = true;
  viewportState.compact = false;
  sidebarState.showing = true;
  panelFullScreenState.isMainCollapsed = false;
  panelGroupLayoutState.layout = [100, 0];
  commandHandlers.clear();
  commandPresentationState.isModifierHeld = false;
  commandPresentationState.shortcut = null;
  threadStore.set("thr-a", { archivedAt: null, deletedAt: null });
  threadStore.set("thr-b", { archivedAt: null, deletedAt: null });
});

afterEach(() => {
  cleanup();
  threadStore.clear();
  panelCallbacks.clear();
  resetPluginSlotStoreForTest();
  delete window.bbDesktop;
  window.localStorage.clear();
  window.sessionStorage.clear();
});

describe("SplitThreadArea", () => {
  it("maximizes without changing the split tree and restores mounted pane state", async () => {
    const initialLayout = twoPaneLayout("pane-1");
    const store = renderSplitArea({
      path: threadPath("thr-a"),
      layout: initialLayout,
    });
    fireEvent.change(await screen.findByTestId("draft-thr-b"), {
      target: { value: "preserve this hidden draft" },
    });

    fireEvent.click(screen.getByTestId("maximize-thr-a"));

    const paneA = document.querySelector<HTMLElement>(
      '[data-split-pane-id="pane-1"]',
    );
    const paneB = document.querySelector<HTMLElement>(
      '[data-split-pane-id="pane-2"]',
    );
    expect(paneA?.getAttribute("data-maximized")).toBe("true");
    expect(paneA?.className).toContain("absolute");
    expect(paneB?.className).toContain("invisible");
    expect(paneB?.getAttribute("aria-hidden")).toBe("true");
    expect(paneB?.style.contentVisibility).toBe("hidden");
    expect(screen.getByTestId("draft-thr-b")).toBeTruthy();
    expect(store.get(splitLayoutAtom)?.root).toEqual(initialLayout.root);
    expect(store.get(maximizedPaneIdAtom)).toBe("pane-1");

    fireEvent.click(screen.getByTestId("maximize-thr-a"));

